window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-f6efcc891d5bfb84"]={"versions": [{"id": "FIG-f6efcc891d5bfb84", "releases": ["R2.1.20", "R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Simulink-Blockschaltbild / Modellierungsansicht eines AUTOSAR-Software-Components (SWC) innerhalb der MATLAB/Simulink-Umgebung. Dargestellt ist der interne Aufbau einer Runnable Entity („Sensor Actuator Runnable“) einer Sensor-Actuator-Softwarekomponente zur Vorbereitung auf die automatische Codegenerierung über TargetLink oder Embedded Coder/Real-Time Workshop im AUTOSAR-Entwicklungsprozess.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Modell enthält folgende Elemente:</p>\n<ul class=\"fig-list\"><li>Trigger-Block: <code>RteEvent</code> (Function-Call / Triggered Subsystem Execution).\n</li><li>Eingangsports (Inports):\n<ul class=\"fig-list\"><li>Inport 1 (<code>ECUABDE_1</code>): Datenelement aus dem Receive-Port der ECU-Abstraktionsschicht („Receive port from the ECU Abstraction“).\n</li><li>Inport 2 (<code>DE_5</code>): Datenelement.\n</li></ul>\n</li><li>Verarbeitungsblöcke:\n<ul class=\"fig-list\"><li>Addierer/Subtrahierer (<code>+-</code>) mit Rückführung.\n</li><li>Zeitdiskreter Differenzblock (<code>(z-1)/z Difference</code>), der das Signal <code>DE_a</code> erzeugt.\n</li><li>Vorzeichenblock (<code>Sign</code>), der das Signal <code>DE_e</code> erzeugt.\n</li><li>Verstärkungsblock (<code>Gain</code>, Faktor 2), der das Signal <code>ECUABDE_a</code> erzeugt.\n</li><li>Client-Port-Subsystemblock (<code>Client port to the ECU Abstraction</code>) für synchrone/asynchrone Client-Server-Kommunikation mit der ECU-Abstraktion.\n</li></ul>\n</li><li>Ausgangsports (Outports):\n<ul class=\"fig-list\"><li>Outport 1 (<code>DE_a</code>): Bereitgestelltes Datenelement.\n</li><li>Outport 2 (<code>DE_e</code>): Bereitgestelltes Datenelement.\n</li><li>Outport 3 (<code>ECUABDE_a</code>): Datenelement für den Provide-Port an die ECU-Abstraktionsschicht („Provide port to the ECU Abstraction“).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Abarbeitung der Runnable wird durch ein <code>RteEvent</code> getriggert (periodisches Timing-Event oder Datenempfangs-Event). Bei Ausführung werden die Eingangsdaten über die RTE eingelesen (<code>ECUABDE_1</code> und <code>DE_5</code>). Das Eingangssignal <code>ECUABDE_1</code> wird über ein diskretes Filter/Differenzglied verarbeitet und an Outport 1 (<code>DE_a</code>) sowie als Rückführung bereitgestellt. Das Signal <code>DE_5</code> durchläuft einen Vorzeichenblock (<code>Sign</code>) und wird an Outport 2 (<code>DE_e</code>) sowie an das Subsystem <code>Client port to the ECU Abstraction</code> geleitet. Das Client-Port-Subsystem interagiert mit der ECU-Abstraktion; dessen Antwort wird über den <code>Gain</code>-Block skaliert, rückgekoppelt und als Signal <code>ECUABDE_a</code> an Outport 3 ausgegeben.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Modellierungsrichtlinie für AUTOSAR-konforme Simulink-Modelle von Runnable Entities: Ports und Signale müssen exakt den Schnittstellendefinitionen der Software-Komponentenbeschreibung (SWC Description) entsprechen (Sender-Receiver-Kommunikation via Inports/Outports sowie Client-Server-Aufrufe über dedizierte Subsysteme). Die Benennung der Ports und Signale korrespondiert mit den AUTOSAR-Datenelementen (<code>DE_*</code>, <code>ECUABDE_*</code>). Die zeitdiskreten Blöcke setzen eine konsistente Abtastrate gemäß der RteEvent-Periodizität voraus.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-e1e8611082d4db35", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Simulink-Blockschaltbild / Modellierungsansicht eines AUTOSAR-Software-Components (SWC) innerhalb der MATLAB/Simulink-Umgebung. Dargestellt ist der interne Aufbau einer Runnable Entity („Sensor Actuator Runnable“) einer Sensor-Actuator-Softwarekomponente zur Vorbereitung auf die automatische Codegenerierung über TargetLink oder Embedded Coder/Real-Time Workshop im AUTOSAR-Entwicklungsprozess.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Modell enthält folgende Elemente:</p>\n<ul class=\"fig-list\"><li>Trigger-Block: <code>RteEvent</code> (Function-Call / Triggered Subsystem Execution).\n</li><li>Eingangsports (Inports):\n<ul class=\"fig-list\"><li>Inport 1 (<code>ECUABDE_1</code>): Datenelement aus dem Receive-Port der ECU-Abstraktionsschicht („Receive port from the ECU Abstraction“).\n</li><li>Inport 2 (<code>DE_5</code>): Datenelement.\n</li></ul>\n</li><li>Verarbeitungsblöcke:\n<ul class=\"fig-list\"><li>Addierer/Subtrahierer (<code>+-</code>) mit Rückführung.\n</li><li>Zeitdiskreter Differenzblock (<code>(z-1)/z Difference</code>), der das Signal <code>DE_a</code> erzeugt.\n</li><li>Vorzeichenblock (<code>Sign</code>), der das Signal <code>DE_e</code> erzeugt.\n</li><li>Verstärkungsblock (<code>Gain</code>, Faktor 2), der das Signal <code>ECUABDE_a</code> erzeugt.\n</li><li>Client-Port-Subsystemblock (<code>Client port to the ECU Abstraction</code>) für synchrone/asynchrone Client-Server-Kommunikation mit der ECU-Abstraktion.\n</li></ul>\n</li><li>Ausgangsports (Outports):\n<ul class=\"fig-list\"><li>Outport 1 (<code>DE_a</code>): Bereitgestelltes Datenelement.\n</li><li>Outport 2 (<code>DE_e</code>): Bereitgestelltes Datenelement.\n</li><li>Outport 3 (<code>ECUABDE_a</code>): Datenelement für den Provide-Port an die ECU-Abstraktionsschicht („Provide port to the ECU Abstraction“).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Abarbeitung der Runnable wird durch ein <code>RteEvent</code> getriggert (periodisches Timing-Event oder Datenempfangs-Event). Bei Ausführung werden die Eingangsdaten über die RTE eingelesen (<code>ECUABDE_1</code> und <code>DE_5</code>). Das Eingangssignal <code>ECUABDE_1</code> wird über ein diskretes Filter/Differenzglied verarbeitet und an Outport 1 (<code>DE_a</code>) sowie als Rückführung bereitgestellt. Das Signal <code>DE_5</code> durchläuft einen Vorzeichenblock (<code>Sign</code>) und wird an Outport 2 (<code>DE_e</code>) sowie an das Subsystem <code>Client port to the ECU Abstraction</code> geleitet. Das Client-Port-Subsystem interagiert mit der ECU-Abstraktion; dessen Antwort wird über den <code>Gain</code>-Block skaliert, rückgekoppelt und als Signal <code>ECUABDE_a</code> an Outport 3 ausgegeben.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Modellierungsrichtlinie für AUTOSAR-konforme Simulink-Modelle von Runnable Entities: Ports und Signale müssen exakt den Schnittstellendefinitionen der Software-Komponentenbeschreibung (SWC Description) entsprechen (Sender-Receiver-Kommunikation via Inports/Outports sowie Client-Server-Aufrufe über dedizierte Subsysteme). Die Benennung der Ports und Signale korrespondiert mit den AUTOSAR-Datenelementen (<code>DE_*</code>, <code>ECUABDE_*</code>). Die zeitdiskreten Blöcke setzen eine konsistente Abtastrate gemäß der RteEvent-Periodizität voraus.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-f6efcc891d5bfb84", "to": "FIG-e1e8611082d4db35", "fr": "R3.1.5", "tr": "R3.2.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
